import sys
from collections import deque

def bfs(start, target, graph, n):
    queue = deque([(start, 0)])
    visited = set([start])
    while queue:
        current, moves = queue.popleft()
        if current == target:
            return moves
        for neighbor in range(n):
            if neighbor != current and (current, neighbor) not in visited and graph[current][neighbor] == graph[start][current]:
                visited.add((current, neighbor))
                visited.add((neighbor, current))
                queue.append((neighbor, moves + 1))
    return float('inf')

def find_solution(n, stones, colors):
    stones = sorted(stones)
    target_positions = [0, 1, 2]
    min_moves = float('inf')
    best_path = []

    def dfs(current_stones, moves, path):
        nonlocal min_moves, best_path
        if current_stones == target_positions:
            if moves < min_moves:
                min_moves = moves
                best_path = path[:]
            return
        for i in range(3):
            for j in range(n):
                if j not in current_stones and colors[current_stones[i]][j] == colors[current_stones[i]][current_stones[(i + 1) % 3]]:
                    new_stones = current_stones[:]
                    new_stones[i] = j
                    new_stones.sort()
                    if tuple(new_stones) not in visited:
                        visited.add(tuple(new_stones))
                        path.append((current_stones[i] + 1, j + 1))
                        dfs(new_stones, moves + 1, path)
                        path.pop()

    visited = set()
    visited.add(tuple(stones))
    dfs(stones, 0, [])

    if min_moves == float('inf'):
        return -1
    return f"{min_moves}\n" + "\n".join(f"{a} {b}" for a, b in best_path)

input = sys.stdin.read().strip().split('\n')
n = int(input[0])
stones = list(map(int, input[1].split()))
colors = [list(line) for line in input[2:]]

result = find_solution(n, stones, colors)
print(result)
